/bin/bash -lc "npm test && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createReportService } from './src/server.js';
let sent=[]; const s=createReportService({deliver:x=>sent.push(x), now:()=>new Date('2026-08-10T09:00:00Z')});
const x=s.createSchedule({accountId:'a',email:'a@example.com',frequency:'daily',time:'09:00'});
assert.equal(s.listSchedules().length,1); await s.tick(); assert.equal(sent.length,1); await s.run(x.id); assert.equal(s.listDeliveries().length,2); console.log('schedule smoke test passed');
NODE"

